using Microsoft.AspNetCore.Mvc;
using WebDogApp.Core.Contracts;
using WebDogApp.Models.Breed;
namespace WebDogApp.Controllers;
public class BreedController : Controller { private readonly IBreedService _service; public BreedController(IBreedService service){_service=service;} public IActionResult Index()=>View(_service.GetBreeds().Select(b=>new BreedVM{Id=b.Id,Name=b.Name}).ToList()); public IActionResult Create()=>View(new BreedVM()); [HttpPost][ValidateAntiForgeryToken] public IActionResult Create(BreedVM model){if(!ModelState.IsValid)return View(model);if(_service.Create(model.Name))return RedirectToAction(nameof(Index));return View(model);} public IActionResult Edit(int id){var b=_service.GetBreedById(id);if(b==null)return NotFound();return View(new BreedVM{Id=b.Id,Name=b.Name});} [HttpPost][ValidateAntiForgeryToken] public IActionResult Edit(int id,BreedVM model){if(!ModelState.IsValid)return View(model);if(_service.Update(id,model.Name))return RedirectToAction(nameof(Index));return NotFound();} public IActionResult Delete(int id){var b=_service.GetBreedById(id);if(b==null)return NotFound();return View(new BreedVM{Id=b.Id,Name=b.Name});} [HttpPost][ValidateAntiForgeryToken] public IActionResult DeleteConfirmed(int id){if(!_service.Delete(id)){TempData["BreedError"]="Породата не може да бъде изтрита, защото има кучета от нея.";}return RedirectToAction(nameof(Index));} }
